#!/usr/bin/env python3
"""Assemble the Phase 3 report (markdown) from derived/phase3/*.csv. Usage: python3 analysis/phase3_report.py runs/<v8 folder> documents/<out.md>"""
import sys, os, numpy as np, pandas as pd
ROOT = os.path.expanduser('~/Claude/bolivia-enso'); P3 = f'{ROOT}/derived/phase3'; RUN = os.path.basename(sys.argv[1].rstrip('/')); OUT = sys.argv[2]
NAME = {'SB': 'Soya', 'MZ': 'Maíz', 'RI': 'Arroz', 'SG': 'Sorgo', 'WH': 'Trigo'}; CROPS = ['SB', 'MZ', 'RI', 'SG', 'WH']
enso = pd.read_csv(f'{ROOT}/derived/enso_classification_1983-2024.csv'); comp = pd.read_csv(f'{P3}/yield_composites_simulated.csv'); ser = pd.read_csv(f'{P3}/yield_series_simulated.csv')
pw = pd.read_csv(f'{P3}/weather_composites_power.csv'); se = pd.read_csv(f'{P3}/weather_composites_senamhi.csv'); st = pd.read_csv(f'{P3}/senamhi_stations.csv'); ia = pd.read_csv(f'{P3}/ine_event_anomalies.csv')
def f(x, d=0, sign=True): return ('' if np.isnan(x) else (f'{x:+.{d}f}' if sign else f'{x:.{d}f}'))
def ci(r): return f"{f(r.mean_anom_pct)}% [{f(r.ci_lo)}, {f(r.ci_hi)}]" + ('**' if r.distinct_from_neutral else '')
L = []; w = L.append
w(f"# Phase 3 — Historical ENSO assessment, Bolivia 1983/84–2024/25\n\nDraft 2026-10-05. Reference run `{RUN}` (Tapiti, Phase 2 calibration). Companion to `PLAN.md` §8. Tables are generated by `analysis/phase3_report.py` from `derived/phase3/`; figures in `derived/phase3/figures/`.\n")
w("## 1. What this is and is not\n\nTwo lines of evidence, kept separate as the plan requires. **(b) Mechanistic:** Tapiti simulations of every campaign 1983/84–2024/25 under observed NASA POWER weather, with everything but weather held constant, composited by ENSO phase — differences between phases are attributable to climate alone. **(a) Statistical:** observed yields (INE departmental series) and observed weather (SENAMHI stations) against the same ENSO classification — no crop model involved, but confounded by prices, area, technology and policy. Where the two agree the finding is robust; where they diverge the gap is informative. Anomalies are **detrended** (linear, per series) and expressed in % of the trend mean; intervals are 95% bootstrap intervals of the phase mean (years resampled within phase). `**` marks a phase whose difference from neutral years has a 95% interval excluding zero.\n")
# ENSO classification
cnt = enso.category.value_counts()
w("## 2. ENSO classification of the 42 campaigns\n\nDJF ONI (CPC, ERSSTv5) labelled by the campaign's sowing year; ±0.5 °C threshold, strong ≥ 1.5. The eastern-Pacific refinement uses the DJF Niño-1+2 anomaly: **strong EP analogues** are strong El Niño campaigns with Niño-1+2 ≥ +1.0 °C — 1997/98, 2015/16 and 2023/24. 1982/83, the other benchmark, pre-dates the simulated record (weather from 1981, first sowing 1983).\n")
w(f"| Category | Campaigns | Which |\n|---|---|---|\n" + '\n'.join(f"| {c} | {cnt[c]} | {', '.join(enso[enso.category == c].campaign)} |" for c in ['strong El Niño', 'moderate El Niño', 'weak El Niño', 'neutral', 'weak La Niña', 'moderate La Niña', 'strong La Niña'] if c in cnt) + "\n")
w(f"Strong El Niño campaigns and their eastern-Pacific weighting (Niño-1+2 minus Niño-3.4, DJF): " + '; '.join(f"{r.campaign} ONI {r.oni_djf:+.1f}, N1+2 {r.nino12_djf:+.1f}, EP−CP {r.ep_minus_cp:+.1f}" for r in enso[enso.category == 'strong El Niño'].itertuples()) + ". 1991/92 is a central-Pacific event (N1+2 +0.6) and behaves differently below. The 2026/27 event is forecast at Niño-1+2 ≈ +3.4 °C, i.e. 1997/98-like.\n")
# Weather check
w("## 3. Is the ENSO signal in the weather? (check before compositing yields)\n\n### 3.1 Observed: SENAMHI station rainfall, Nov–Mar totals\n")
w(f"{len(st)} stations with monthly precipitation ({st.zone.value_counts().to_dict()}), records 1970–2009, so the composites cover campaigns 1983/84–2008/09 only and the only strong-EP analogue inside the record is **1997/98**. Anomalies are % of each station's own Nov–Mar mean, averaged across stations.\n")
t = se[se.group.isin(['Bolivia', 'lowland', 'valleys', 'altiplano'])].pivot(index='group', columns='phase', values='mean').loc[['Bolivia', 'lowland', 'valleys', 'altiplano']]
w("| Zone | El Niño (8) | La Niña (10) | Neutral (8) | Strong El Niño 1991/92 + 1997/98 | 1997/98 |\n|---|---|---|---|---|---|\n" + '\n'.join(f"| {z} | {f(r['El Niño'])}% | {f(r['La Niña'])}% | {f(r['neutral'])}% | {f(r['strong El Niño (ONI≥1.5)'])}% | {f(r['strong EP analogues 1997/2015/2023'])}% |" for z, r in t.iterrows()) + "\n")
alt = se[(se.group == 'altiplano') & (se.phase == 'El Niño')].iloc[0]; val = se[(se.group == 'valleys') & (se.phase == 'El Niño')].iloc[0]
w(f"The classic picture is present in the observations: El Niño campaigns are drier in the Altiplano ({f(alt['mean'])}%, 95% CI [{f(alt.ci_lo)}, {f(alt.ci_hi)}]) and valleys ({f(val['mean'])}%, [{f(val.ci_lo)}, {f(val.ci_hi)}]) and not drier in the lowlands; La Niña is wetter everywhere. 1997/98 alone was −35% in the Altiplano, −16% in the valleys, −9% in the lowlands. Potosí stations show the largest El Niño deficit (−15% all events, −42% in 1997/98).\n")
w("### 3.2 Model input: NASA POWER, area-weighted over the modelled cells\n")
t = pw[(pw.departamento == 'Bolivia') & (pw.variable == 'rain_v')].pivot(index='zone', columns='phase', values='mean').loc[['all', 'lowland', 'valleys', 'altiplano']]
t2 = pw[(pw.departamento == 'Bolivia') & (pw.variable == 'tmax_v')].pivot(index='zone', columns='phase', values='mean').loc[['all', 'lowland', 'valleys', 'altiplano']]
w("Nov–Mar rainfall anomaly (% of mean) and Tmax anomaly (°C), 1983/84–2024/25:\n\n| Zone | El Niño (14) | La Niña (16) | Neutral (12) | Strong El Niño (4) | Strong EP analogues (3) | Tmax: El Niño | La Niña | Strong EP |\n|---|---|---|---|---|---|---|---|---|\n" + '\n'.join(f"| {z} | {f(r['El Niño'])}% | {f(r['La Niña'])}% | {f(r['neutral'])}% | {f(r['strong El Niño (ONI≥1.5)'])}% | {f(r['strong EP analogues 1997/2015/2023'])}% | {f(t2.loc[z, 'El Niño'], 1)} | {f(t2.loc[z, 'La Niña'], 1)} | {f(t2.loc[z, 'strong EP analogues 1997/2015/2023'], 1)} |" for z, r in t.iterrows()) + "\n")
w("Two things follow. First, **the reanalysis under-represents the observed El Niño drying of the Altiplano** (−5% in POWER vs −11% at the stations for all El Niño campaigns), which is the expected weakness of a 0.5° product in the Andes (PLAN §10) and means Altiplano results below are conservative at best. Second, in both datasets **the signal is carried by the strong eastern-Pacific events, not by El Niño as a class**: the all-El-Niño composite is within a few percent of neutral, while 1997/98, 2015/16 and 2023/24 bring 17–19% less rain and 1.6–2.1 °C hotter days in every zone. The 2026/27 event belongs to that class.\n")
# Simulated composites
w("## 4. Simulated yield anomalies by ENSO phase (mechanistic line)\n\nNational, area-weighted, detrended; `**` = difference from neutral years distinguishable from zero at 95%.\n")
nat = comp[(comp.departamento == 'Bolivia') & (comp.zone == 'all')]
phases = ['La Niña', 'neutral', 'El Niño', 'strong El Niño (ONI≥1.5)', 'strong EP analogues 1997/2015/2023']
w("| Crop | " + ' | '.join(phases) + " |\n|---|" + '---|' * len(phases) + "\n" + '\n'.join(f"| {NAME[c]} | " + ' | '.join(ci(nat[(nat.crop == c) & (nat.phase == ph)].iloc[0]) for ph in phases) + ' |' for c in CROPS) + "\n")
w("![national composites](../derived/phase3/figures/chart_phase_composites_national.png)\n")
sep = nat[nat.phase == 'strong EP analogues 1997/2015/2023'].set_index('crop')
w(f"**Reading.** El Niño as a class does nothing to the verano crops (soya, maíz, arroz within ±2% of neutral). The strong eastern-Pacific analogues are a different matter: **soya {f(sep.loc['SB'].mean_anom_pct)}%, maíz {f(sep.loc['MZ'].mean_anom_pct)}%, arroz {f(sep.loc['RI'].mean_anom_pct)}%**, each with an interval excluding zero, and each individual event negative. The **invierno crops gain**: sorgo {f(sep.loc['SG'].mean_anom_pct)}% and trigo {f(sep.loc['WH'].mean_anom_pct)}%. Note the timing: a campaign labelled by sowing year *y* pairs the invierno sown in April–June of *y* with the El Niño that peaks the following DJF, so this is the **developing-El Niño winter** (invierno 1997, 2015, 2023), which is wetter in the eastern lowlands, not the winter after the peak; symmetrically, the developing-La Niña winter costs sorgo {f(nat[(nat.crop == 'SG') & (nat.phase == 'La Niña')].iloc[0].mean_anom_pct)}% (interval excluding zero) and trigo {f(nat[(nat.crop == 'WH') & (nat.phase == 'La Niña')].iloc[0].mean_anom_pct)}%. That asymmetry — verano losers after the peak, invierno winners during the build-up — is the central finding of this phase and it matches the INE record where the two overlap (§5). For 2026/27 it means the invierno 2026 crops (already harvested) are the beneficiaries and the verano 2026/27 crops the exposed ones.\n")
w("### 4.1 By zone\n")
z = comp[(comp.departamento == 'Bolivia') & (comp.zone != 'all')]
w("| Crop | Zone | kha | El Niño | La Niña | Strong EP analogues | Worst campaign |\n|---|---|---|---|---|---|---|\n" + '\n'.join(f"| {NAME[r.crop]} | {r.zone} | {r.area_kha:.0f} | {ci(z[(z.crop == r.crop) & (z.zone == r.zone) & (z.phase == 'El Niño')].iloc[0])} | {ci(z[(z.crop == r.crop) & (z.zone == r.zone) & (z.phase == 'La Niña')].iloc[0])} | {ci(r)} | {r.worst_year} ({f(r.min_anom_pct)}%) |" for r in z[z.phase == 'strong EP analogues 1997/2015/2023'].sort_values(['crop', 'zone']).itertuples()) + "\n")
w("Lowland maíz and soya carry the strong-EP loss (−27% and −20%); valley maíz −12%. **Altiplano maíz goes the other way (+18% in strong EP years, +12% in all El Niño years)**: in the model the Altiplano crop is cold-limited, so a warmer El Niño summer with fewer frosts outweighs the (under-represented) rainfall deficit. This is where the mechanistic and observed lines diverge most and where the model is least trustworthy (35% of simulated Altiplano maize seasons fail; the reanalysis misses half of the observed drying). Treat the Altiplano maize sign as unresolved, not as a result.\n")
w("![strong EP composite maps](../derived/phase3/figures/map_strongEP_composite_by_crop.png)\n\n![phase composite maps](../derived/phase3/figures/map_phase_composites_maize_soya.png)\n")
# Analogue events
w("## 5. The analogue events, one by one\n\nSimulated national detrended anomaly (%) and, where INE's departmental series exist (2012–2024), the observed detrended anomaly. 1982/83 is outside the simulated record.\n")
ev = ser[(ser.departamento == 'Bolivia') & (ser.zone == 'all')].pivot(index='crop', columns='sow_year', values='anom_detrended_pct')
inat = ia[ia.departamento == 'Bolivia'].pivot_table(index=['crop', 'season'], columns='sow_year', values='ine_anom_detrended_pct')
def obs(crop, y, season):
    try: return f(inat.loc[(crop, season), y])
    except KeyError: return '—'
rows = ["| Crop | 1991/92 (CP, ONI +1.5) | 1997/98 (EP, +2.2) | 2009/10 (CP, +1.5) | 2015/16 (EP, +2.5) | 2015/16 observed | 2023/24 (EP, +1.8) | 2023/24 observed |", "|---|---|---|---|---|---|---|---|"]
for c in CROPS:
    season = 'invierno' if c in ('SG', 'WH') else 'verano'
    rows.append(f"| {NAME[c]} ({season}) | {f(ev.loc[c, 1991])} | {f(ev.loc[c, 1997])} | {f(ev.loc[c, 2009])} | {f(ev.loc[c, 2015])} | {obs(c, 2015, season)} | {f(ev.loc[c, 2023])} | {obs(c, 2023, season)} |")
w('\n'.join(rows) + '\n')
o15 = {c: obs(c, 2015, 'invierno' if c in ('SG', 'WH') else 'verano') for c in CROPS}; o23 = {c: obs(c, 2023, 'invierno' if c in ('SG', 'WH') else 'verano') for c in CROPS}
w(f"\n- **1997/98** — the strongest eastern-Pacific event in the record (Niño-1+2 +3.5 °C). POWER: −17% rain, +2 °C Tmax across zones; SENAMHI stations: −35% Altiplano, −16% valleys. Simulated maíz −19%, arroz −28%, soya −18%; invierno sorgo +16%, trigo +15%. No INE departmental series for validation.\n- **2015/16** — ONI +2.5, Niño-1+2 +1.8. Simulated maíz −29% (the worst maize campaign of the 42), soya −27%, arroz −13%; sorgo +24%, trigo +25%. Observed (INE, detrended): soya verano {o15['SB']}, maíz {o15['MZ']}, arroz {o15['RI']}; sorgo invierno {o15['SG']}, trigo invierno {o15['WH']}. The model and the record agree on arroz and sorgo and on the sign for maíz; **they disagree on soya**, where the record shows no loss — consistent with §7.3c of the plan (the model loves rainfall, Santa Cruz soya does not).\n- **2023/24** — ONI +1.8, Niño-1+2 +1.3. Simulated soya −16%, arroz −12%, maíz −5%; sorgo +38%. Observed: soya {o23['SB']}, arroz {o23['RI']}, maíz {o23['MZ']}; sorgo invierno {o23['SG']}, trigo {o23['WH']}. **Close agreement on every crop** — the best-validated event, and the most recent.\n- **1991/92 and 2009/10 (central-Pacific, ONI +1.5)** — simulated verano crops *gain* (maíz +0/+23, soya +4/+14) and invierno crops gain too. A CP El Niño is not a drought year for Bolivia in either the model or the weather. This is why the composite must be stratified by Niño-1+2: the 2026/27 event is EP.\n- **La Niña for contrast, 2010/11 (ONI −1.3)**: simulated soya and sorgo both at their record lows (§7.0 of the plan); the Santa Cruz drought of that winter is in the record.\n")
# INE statistical line
w("## 6. Observed yields by phase (statistical line), 2012–2024 only\n\nINE departmental series exist only from 2012; thirteen campaigns, five El Niño (two strong), four La Niña, three to four neutral. Means of detrended national anomalies (%):\n")
t = ia[ia.departamento == 'Bolivia'].groupby(['crop', 'season', 'phase']).ine_anom_detrended_pct.mean().unstack('phase')
w("| Crop, season | El Niño (5) | La Niña (4) | Neutral (3–4) |\n|---|---|---|---|\n" + '\n'.join(f"| {NAME[c]} {s} | {f(r['El Niño'])} | {f(r['La Niña'])} | {f(r['neutral'])} |" for (c, s), r in t.iterrows() if (s == 'verano' and c in ('SB', 'MZ', 'RI')) or (s == 'invierno' and c in ('SG', 'WH'))) + "\n")
w("Thirteen years cannot support phase composites; the per-event table in §5 is the honest use of this record. Its one robust message is the **invierno gain in the developing-El Niño winter**: observed sorgo invierno was +16% in 2015 and +43% in 2023, trigo invierno +17% in 2023 — the same asymmetry the model produces from weather alone.\n")
# Significance statement
w("## 7. What is distinguishable from zero, and what is not\n\n")
sig = nat[nat.distinct_from_neutral].sort_values(['crop', 'phase'])
w("Distinguishable from neutral at 95% (national, bootstrap over years): " + '; '.join(f"{NAME[r.crop]} under {r.phase} ({f(r.mean_anom_pct)}%, n={r.n_years})" for r in sig.itertuples()) + ".\n\n**Not** distinguishable: every verano crop under El Niño or La Niña as a class; trigo under any phase except its La Niña loss being borderline; everything in the Altiplano. The strong-EP composites rest on **three events** — their intervals are narrow because the three agree, not because three is many. Report them as \"in the three eastern-Pacific El Niño campaigns since 1983\", never as a climatological expectation.\n")
# Caveats
w("## 8. Caveats that travel with these numbers\n\n- **Soya** (1.4 Mha): the model's weather response is wrong in a specific way — it gains from rainfall and wet days where the record is indifferent or loses (PLAN §7.3c). Its strong-EP loss (−20%) comes through heat and dry spells, which it does get right, so the sign is defensible; the magnitude is not, and 2015/16 shows the record can disagree. The model's −1.25%/yr soya trend was removed before compositing.\n- **Altiplano**: reanalysis rainfall misses half the observed El Niño deficit; Altiplano maize fails in a third of simulated seasons; potato and quinoa are absent. The highland drought story has to come from the station record and INE, not from this model.\n- **Levels vs anomalies**: Phase 2 calibrated levels; anomaly skill against INE is 0.66–0.76 for arroz/sorgo/trigo and 0.28–0.42 for soya/maíz over twelve years.\n- **No area response, no floods/hail/frost damage, no pests** (PLAN §10). The excess-rain channel that matters for lowland soya in El Niño years is outside the model.\n- **1982/83 is not simulated**; the station record shows it, the model cannot.\n")
w("## 9. Implication for 2026/27 (preview of Phase 4)\n\nIf 2026/27 behaves like the three eastern-Pacific analogues, the model's expectation is a **15–20% national loss in the verano grains and oilseed (maíz, arroz, soya), concentrated in the Santa Cruz plain, while the invierno 2026 sorgo and trigo, grown during the El Niño build-up, should have done well** (Phase 4 confirms this with observed weather), with the Altiplano unresolved by this tool. Phase 4 turns this into a season-specific estimate by driving the 2026/27 calendar with the analogue years' weather and with the C3S seasonal forecasts.\n")
open(OUT, 'w').write('\n'.join(L)); print('wrote', OUT, len('\n'.join(L).split()), 'words')
